GENERIC = {
    'dog': ('강아지', ['강아지', '애견', '애완견', '반려견', '개', '애완용강아지', '댕댕이', '귀여운강아지', '갈색강아지', '티컵강아지', '소형견', '중형견', '대형견', '초미니반려견', '저렴한강아지', '강아지품종', '강아지견종', '강아지종류', '애완견종류']),
    'cat': ('고양이', ['고양이', '반려묘', '새끼고양이', '아기고양이', '저렴한고양이']),
}


def post_title(n):
    f = os.path.join(ROOT, 'raw', 'site', 'text', f'pets_{n}.txt')
    return open(f, encoding='utf-8').readline().split(' | ')[0].replace(' ', '') if os.path.exists(f) else None


def main():
    sys.stdout.reconfigure(encoding='utf-8')
    site = json.load(open(os.path.join(ROOT, 'raw', 'site', 'breeds.json'), encoding='utf-8'))
    out, alias = [], {}
    for bid, name, kind, size, coat, shed, trait, care, s, al in BREEDS:
        key = f"{'dogs' if kind == D else 'cats'}/{s}" if s else None
        photos = [f'{s}-{n}' for n in site[key]['photos']] if key in site else []
        if s and 'special' in s:  # 그외특수견·묘는 여러 품종이 섞여 있어, 분양 글 제목이 이 견종인 사진만 쓴다
            photos = [f'{s}-{n}' for n in site[key]['photos'] if post_title(n) in {a.replace(' ', '') for a in al + [name]}]
        out.append(dict(id=bid, name=name, kind=kind, size=size, coat=coat, shed=shed, trait=trait, care=care,
                        site=s, siteName=site[key]['title'].split(' (')[0] if key in site else None, siteCount=COUNT.get(s), photos=photos))
        for a in set(al + [name]):
            assert a not in alias or alias[a] == bid, (a, alias.get(a), bid)
            alias[a] = bid
    for k, (_, al) in GENERIC.items():
        for a in al: alias[a] = k
    json.dump({'_source': '견종 설명: 일반 품종 특징 / site·siteCount·photos: dorothypet.co.kr 분양 분류 2026-10-27 수집',
               'breeds': out, 'alias': alias}, open(os.path.join(ROOT, 'data', 'breeds.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=0)
    print(f'견종 {len(out)}종, 표기 {len(alias)}개')


if __name__ == '__main__':
    main()
